<script setup>
import {ref,computed} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import Icon from '../components/Icon.vue'
import {people,amenities,lifestyles,districts,money} from '../data'
import {state} from '../store'
const router=useRouter(),route=useRoute(),started=ref(false),detail=ref(false),district=ref(''),gender=ref(''),budget=ref(2000000),selected=ref([]),habits=ref([]),notice=ref(''),locationMode=ref('place')
const candidates=computed(()=>people.filter(p=>!state.passed.includes(p.id)&&!state.likes.includes(p.id)&&(!district.value||p.district===district.value)&&(!gender.value||p.gender===gender.value)&&p.price<=budget.value&&habits.value.every(h=>p.tags.includes(h))))
const current=computed(()=>candidates.value[0])
function react(like){if(like&&!state.user)return router.push('/dang-nhap?redirect=/ghep-tro?start=1');(like?state.likes:state.passed).push(current.value.id);notice.value=like?'Đã lưu sự quan tâm của bạn. Chưa gửi liên hệ thực tế.':'';detail.value=false}
if(route.query.start)started.value=true
</script>
<template><div class="container page"><div v-if="route.query.guide" class="notice"><Icon name="shield"/>Trao đổi rõ giờ giấc, chi phí và việc nhà. Gặp nhau ở nơi công cộng trước khi quyết định ở cùng.</div><div class="breadcrumb"><RouterLink to="/">Trang chủ</RouterLink><Icon name="right" :size="14"/>Ghép trọ</div><div class="match-layout"><aside class="filter-panel"><h2>Tìm người hợp mình</h2><p class="muted">Bắt đầu từ những điều nhỏ trong cuộc sống.</p><h4>Địa điểm</h4><div class="segmented"><button :class="{active:locationMode==='place'}" @click="locationMode='place'">Theo địa điểm</button><button :class="{active:locationMode==='area'}" @click="locationMode='area'">Theo khu vực</button></div><label class="field"><span>{{locationMode==='place'?'Khu vực muốn ở':'Khu vực gần trường'}}</span><select v-model="district"><option value="">Tất cả địa điểm</option><option v-for="d in districts" :key="d">{{d}}</option></select></label><label class="field"><span>Đối tượng</span><select v-model="gender"><option value="">Tất cả</option><option>Nam</option><option>Nữ</option></select></label><label class="field"><span>Mức giá / người <strong>{{money(budget)}}</strong></span><input type="range" min="500000" max="5000000" step="100000" v-model="budget"></label><h4>Tiện ích</h4><div class="checks-two"><label v-for="a in amenities.slice(0,6)" :key="a" class="check"><input type="checkbox" :value="a" v-model="selected">{{a}}</label></div><p v-if="selected.length" class="help">Tiện ích được lưu làm mong muốn; hồ sơ mẫu chưa có đủ dữ liệu để lọc theo tiện ích.</p><h4>Phong cách sống</h4><div class="checks-two"><label v-for="a in ['Yên tĩnh','Không hút thuốc','Gọn gàng','Nuôi thú cưng']" :key="a" class="check"><input type="checkbox" :value="a" v-model="habits">{{a}}</label></div><button class="button primary full" @click="started=true;notice=''">Bắt đầu ghép trọ <Icon name="arrow" :size="18"/></button><RouterLink to="/dang-bai/roommate" class="button secondary full">Đăng bài ghép trọ <Icon name="plus" :size="18"/></RouterLink></aside><section class="match-stage"><span class="eyebrow">Cùng một mái nhà, cùng nhịp sống</span><h1>Không chỉ tìm phòng.<br>Tìm người đồng hành.</h1><div v-if="!started" class="match-welcome"><img src="/illustrations/friends.svg" alt="Hai người bạn ở cùng"><h3>Một người bạn phù hợp đang chờ</h3><p class="muted">Chọn khu vực và lối sống, rồi bắt đầu kết nối.</p></div><template v-else-if="current"><article class="person-card" :key="current.id"><div class="person-portrait" :style="{background:current.color}"><img src="/illustrations/person.svg" :alt="'Minh họa hồ sơ '+current.name"><span class="badge"><Icon name="shield" :size="13"/>Hồ sơ mẫu</span></div><div class="person-info"><div class="section-heading"><h2>{{current.name}}, {{current.age}}</h2><span class="muted">{{current.gender}}</span></div><p class="location"><Icon name="building" :size="16"/>{{current.school}}</p><p class="location muted"><Icon name="pin" :size="16"/>{{current.district}}, Cần Thơ</p><div class="tags"><span v-for="t in current.tags" :key="t">{{t}}</span></div><p class="person-budget">{{money(current.price)}}<span> / người / tháng</span></p><p v-if="detail">{{current.bio}}<br><small class="muted">Ngành học: {{current.major}}</small></p></div></article><div class="match-actions"><button class="match-action pass" @click="react(false)"><Icon name="close" :size="26"/><span>Bỏ qua</span></button><button class="match-action" @click="detail=!detail" :aria-expanded="detail"><Icon name="info" :size="25"/><span>{{detail?'Thu gọn':'Xem chi tiết'}}</span></button><button class="match-action like" @click="react(true)"><Icon name="heart" :size="26"/><span>Quan tâm</span></button></div></template><div v-else class="empty-state"><Icon name="users" :size="42"/><h2>Bạn đã xem hết hồ sơ phù hợp</h2><p>Thử đổi bộ lọc hoặc xem lại các hồ sơ mẫu.</p><button class="button primary" @click="state.passed=[];state.likes=[];district='';gender='';habits=[];budget=2000000">Xem lại hồ sơ</button></div><p v-if="notice" class="notice" role="status">{{notice}}</p></section></div></div></template>
